export type ParsedRecordPaycheckInstruction<
  TProgram extends string = typeof PAYCHECK_ROUTER_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    recorder: TAccountMetas[0];
    payer: TAccountMetas[1];
    config: TAccountMetas[2];
    router: TAccountMetas[3];
    payIn: TAccountMetas[4];
    paycheck: TAccountMetas[5];
    systemProgram: TAccountMetas[6];
  };
  data: RecordPaycheckInstructionData;
};

export function parseRecordPaycheckInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRecordPaycheckInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      recorder: getNextAccount(),
      payer: getNextAccount(),
      config: getNextAccount(),
      router: getNextAccount(),
      payIn: getNextAccount(),
      paycheck: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getRecordPaycheckInstructionDataDecoder().decode(instruction.data),
  };
}
